/* Solutions data loader with a static-host fallback (2026-10-29).
 *
 * GET /api/solutions only answers while the Express backend runs. GitHub
 * Pages serves this storefront with no Node process, so on the public
 * deployment that route 404s -- solutions.html, recommended.html and
 * compare.html used to show a visitor "Temporarily unavailable" and nothing
 * else. This loader falls back to the committed snapshot
 * (customer_site/solutions.json, generated by
 * scripts/export_public_solutions.py from the same engine the live route
 * calls) and reports which source actually answered, so a page never
 * presents snapshot data as live data.
 *
 *   window.gfLoadSolutions()      -> Promise<data>  (rejects if both fail)
 *   window.gfSolutionsSourceNote(data) -> string    ('' when live)
 */
(function () {
  "use strict";

  var SNAPSHOT = "solutions.json";

  function normalize(data, source) {
    if (!data || data.success !== true || !Array.isArray(data.solutions)) return null;
    data.__source = source;
    return data;
  }

  function getJson(url, init) {
    return fetch(url, init).then(function (r) {
      if (!r.ok) throw new Error("HTTP " + r.status);
      return r.json();
    });
  }

  window.gfLoadSolutions = function () {
    return getJson("/api/solutions", { credentials: "same-origin" })
      .then(function (d) {
        var live = normalize(d, "live");
        if (!live) throw new Error("unusable live payload");
        return live;
      })
      .catch(function () {
        return getJson(SNAPSHOT, { cache: "no-store" }).then(function (d) {
          var snap = normalize(d, "snapshot");
          if (!snap) throw new Error("unusable snapshot");
          return snap;
        });
      });
  };

  window.gfSolutionsSourceNote = function (data) {
    if (!data || data.__source !== "snapshot") return "";
    var when = data.generated_at ? " generated " + String(data.generated_at).slice(0, 10) : "";
    return " Static snapshot" + when + " — this host has no backend, so click tracking is unavailable and each link goes straight to the vendor's own official page.";
  };
})();
